    public void test_typesAreCachedInScopeAndInvalidatedByChanges() throws Exception {
      initTestNodes();
      runWithinCommand(() -> {
        final SNode plusNode = getAnnotatedNode("plus");
        final SNode twoNode = getAnnotatedNode("two");
        SNode unscoped1 = TypecheckingFacade.getFromContext().getTypeOf(plusNode);
        SNode unscoped2 = TypecheckingFacade.getFromContext().getTypeOf(plusNode);
        // without a scope every query computes a fresh type; this makes the identity checks below meaningful
        Assert.assertEquals("two unscoped queries of 1 + 2 return different type nodes", false, unscoped1 == unscoped2);
        final String before = SNodeOperations.present(unscoped1);

        final List<SNode> types = ListSequence.fromList(new ArrayList<SNode>());
        InterpreterTestRunScope.withScope(myProject.getRepository(), () -> {
          ListSequence.fromList(types).addElement(TypecheckingFacade.getFromContext().getTypeOf(plusNode));
          ListSequence.fromList(types).addElement(TypecheckingFacade.getFromContext().getTypeOf(plusNode));
          SPropertyOperations.assign(twoNode, PROPS.value$iWTK, "5");
          ListSequence.fromList(types).addElement(TypecheckingFacade.getFromContext().getTypeOf(plusNode));
          SNode detached = SNodeOperations.copyNode(plusNode);
          ListSequence.fromList(types).addElement(TypecheckingFacade.getFromContext().getTypeOf(detached));
          ListSequence.fromList(types).addElement(TypecheckingFacade.getFromContext().getTypeOf(detached));
        });
        String after = SNodeOperations.present(TypecheckingFacade.getFromContext().getTypeOf(plusNode));
        Assert.assertEquals("changing 1 + 2 into 1 + 5 changes its type, " + before + " before and " + after + " after", false, before.equals(after));
        Assert.assertEquals("in a scope, a second query of 1 + 2 returns the cached type node", true, ListSequence.fromList(types).getElement(0) == ListSequence.fromList(types).getElement(1));
        Assert.assertEquals("the cached type of 1 + 2 is the unscoped one", before, SNodeOperations.present(ListSequence.fromList(types).getElement(0)));
        Assert.assertEquals("after the literal changed, the scope answers the new type of 1 + 5", after, SNodeOperations.present(ListSequence.fromList(types).getElement(2)));
        Assert.assertEquals("the type of a detached copy is not cached", false, ListSequence.fromList(types).getElement(3) == ListSequence.fromList(types).getElement(4));
        Assert.assertEquals("the detached copy of 1 + 5 has the type of 1 + 5", after, SNodeOperations.present(ListSequence.fromList(types).getElement(3)));
      });
    }
